CREATE TABLE public.exercise_photo_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.exercise_sessions(id), user_id uuid NOT NULL, prompt text NOT NULL, caption text NOT NULL DEFAULT '', subject text NOT NULL, status text NOT NULL DEFAULT 'queued', storage_path text, error_message text, access_paused boolean NOT NULL DEFAULT false, ip_hash text NOT NULL, inject_id uuid REFERENCES public.exercise_injects(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.exercise_photo_jobs TO authenticated;
GRANT ALL ON public.exercise_photo_jobs TO service_role;
ALTER TABLE public.exercise_photo_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Host reads own photo jobs" ON public.exercise_photo_jobs FOR SELECT TO authenticated USING (user_id=auth.uid() AND public.is_session_host(session_id,auth.uid()) AND public.is_admin(auth.uid()));
CREATE FUNCTION public.limit_photo_generation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('photo_limit',0)); IF (SELECT count(*) FROM public.exercise_photo_jobs WHERE (user_id=NEW.user_id OR ip_hash=NEW.ip_hash) AND created_at>now()-interval '1 hour')>=10 THEN RAISE EXCEPTION 'The hourly limit of 10 photo requests has been reached'; END IF; RETURN NEW; END $$;
CREATE TRIGGER photo_generation_limit BEFORE INSERT ON public.exercise_photo_jobs FOR EACH ROW EXECUTE FUNCTION public.limit_photo_generation();
CREATE POLICY "Session scoped photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='exercise-photos' AND (EXISTS (SELECT 1 FROM public.exercise_photo_jobs j WHERE j.storage_path=name AND j.user_id=auth.uid() AND public.is_session_host(j.session_id,auth.uid())) OR EXISTS (SELECT 1 FROM public.exercise_injects i WHERE i.artefact->>'kind'='photo' AND i.artefact->>'storagePath'=name AND i.is_sent AND public.is_session_participant(i.session_id,auth.uid()))));